from collections import defaultdict

def accuracy_by(rows, key):
    hits, total = defaultdict(int), defaultdict(int)
    for r in rows:              # r: {type, field, correct, confidence}
        total[r[key]] += 1
        hits[r[key]] += r["correct"]
    return {k: round(hits[k] / total[k], 3) for k in total}

